const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Arctic region: 63-90°N, all longitudes
  const arctic = ee.Geometry.Rectangle([-180, 63, 180, 90], null, false);

  // Time periods: April 2011 and April 2014
  const apr2011 = ee.DateRange('2011-04-01', '2011-04-30');
  const apr2014 = ee.DateRange('2014-04-01', '2014-04-30');

  // 2. Data Acquisition - MLS Stratospheric Ozone at 46 hPa
  const mlsCol = ee.ImageCollection('NASA/Aura/MLS/03_DGG')
    .select('O3_46hPa');  // Ozone mixing ratio at 46 hPa (~stratospheric)

  // Filter for each period
  const col2011 = mlsCol.filterDate(apr2011);
  const col2014 = mlsCol.filterDate(apr2014);

  // Check collection sizes
  const count2011 = col2011.size().getInfo();
  const count2014 = col2014.size().getInfo();

  console.log(`April 2011 Images: ${count2011}`);
  console.log(`April 2014 Images: ${count2014}`);

  // Case C1: Empty collection
  if (count2011 === 0 || count2014 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Create monthly composites (mean)
  const img2011 = col2011.mean();
  const img2014 = col2014.mean();

  // Mask unrealistic values (MLS valid range: 0-20 ppmv)
  const maskValid = function(img) {
    return img.updateMask(img.gte(0).and(img.lte(20)));
  };

  const img2011Masked = maskValid(img2011);
  const img2014Masked = maskValid(img2014);

  // 3. Check valid pixels after masking
  const countReducer = ee.Reducer.count();
  const scale = 1000;  // 1km scale for MLS data

  const pixelCount2011 = img2011Masked.reduceRegion({
    reducer: countReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).get('O3_46hPa').getInfo();

  const pixelCount2014 = img2014Masked.reduceRegion({
    reducer: countReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).get('O3_46hPa').getInfo();

  console.log(`Valid Pixels 2011: ${pixelCount2011}`);
  console.log(`Valid Pixels 2014: ${pixelCount2014}`);

  // Case C2: No valid pixels
  if (pixelCount2011 === 0 || pixelCount2014 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate mean ozone concentration for each period
  const meanReducer = ee.Reducer.mean();

  const mean2011 = img2011Masked.reduceRegion({
    reducer: meanReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).get('O3_46hPa').getInfo();

  const mean2014 = img2014Masked.reduceRegion({
    reducer: meanReducer,
    geometry: arctic,
    scale: scale,
    maxPixels: 1e9
  }).get('O3_46hPa').getInfo();

  console.log(`Mean O3 2011: ${mean2011 ? mean2011.toFixed(4) : 'null'} ppmv`);
  console.log(`Mean O3 2014: ${mean2014 ? mean2014.toFixed(4) : 'null'} ppmv`);

  // 5. Validation & Final Answer
  // Case C3: Calculation failure or unrealistic values
  if (mean2011 === null || mean2014 === null || 
      isNaN(mean2011) || isNaN(mean2014) ||
      mean2011 < 0 || mean2011 > 20 || 
      mean2014 < 0 || mean2014 > 20) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare concentrations
  const increase = mean2014 > mean2011;

  // Print evidence
  console.log(`Change: ${((mean2014 - mean2011) / mean2011 * 100).toFixed(1)}%`);

  // Final answer
  if (increase) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
